package GUI;
import Program.model.*; import Program.service.*; import Program.utils.DateUtils; import javafx.collections.FXCollections; import javafx.geometry.*; import javafx.scene.chart.*; import javafx.scene.control.*; import javafx.scene.layout.*; import java.time.*; import java.time.format.TextStyle; import java.util.*;
public class ReportUI extends ScrollPane {private final User user;private final ReportService reports=new ReportService();private final TransactionService transactions=new TransactionService();private final VBox output=new VBox(16);private LocalDate from=DateUtils.firstDayOfMonth(),to=LocalDate.now();private FinancialReport report;
 public ReportUI(User user,MainUI app){this.user=user;setFitToWidth(true);VBox page=UIFactory.page("Financial Reports","Generate actual summaries and compare the last six months.");ComboBox<String>period=new ComboBox<>(FXCollections.observableArrayList("Current Month","Previous Month","Custom Period"));period.setValue("Current Month");DatePicker start=new DatePicker(from),end=new DatePicker(to);Button generate=UIFactory.button("Generate Report","primary-button"),save=UIFactory.button("Save Report","secondary-button");period.setOnAction(e->{if(period.getValue().equals("Current Month")){start.setValue(DateUtils.firstDayOfMonth());end.setValue(LocalDate.now());}else if(period.getValue().equals("Previous Month")){start.setValue(DateUtils.previousMonthStart());end.setValue(DateUtils.previousMonthEnd());}});generate.setOnAction(e->{from=start.getValue();to=end.getValue();if(to.isBefore(from)){UIFactory.error("End date must be after the start date.");return;}build();});save.setOnAction(e->{if(report==null)UIFactory.error("Generate a report first.");else{reports.save(report);UIFactory.info("Report saved","Saved to File/reports/monthly_reports.txt");}});page.getChildren().addAll(new HBox(10,period,start,end,generate,save),output);setContent(page);build();}
 private void build(){report=reports.create(user.getId(),from,to);output.getChildren().clear();HBox cards=new HBox(12,new GUI.components.StatCard("TOTAL INCOME",money(report.getIncome()),"#22C55E"),new GUI.components.StatCard("TOTAL EXPENSES",money(report.getExpenses()),"#EF4444"),new GUI.components.StatCard("BALANCE",money(report.getBalance()),"#38BDF8"),new GUI.components.StatCard("SAVINGS",String.format("%.1f%%",report.getSavingsRate()),"#A78BFA"));cards.getChildren().forEach(x->HBox.setHgrow(x,Priority.ALWAYS));PieChart pie=new PieChart();pie.getStyleClass().add("finance-pie");transactions.expenseByCategory(user.getId(),from,to).forEach((category,value)->pie.getData().add(new PieChart.Data(category+" · "+money(value),value)));BarChart<String,Number>bar=multiMonthChart();HBox charts=new HBox(14,card("Expense Category Analysis",pie),card("Income vs Expenses — Last Six Months",bar));charts.getChildren().forEach(x->{HBox.setHgrow(x,Priority.ALWAYS);((VBox)x).setPrefWidth(500);});Label summary=new Label(clean(report.generateReport()));summary.getStyleClass().add("report-summary");output.getChildren().addAll(cards,charts,summary);}
 private BarChart<String,Number> multiMonthChart(){CategoryAxis xAxis=new CategoryAxis();NumberAxis yAxis=new NumberAxis();xAxis.setLabel("Month");yAxis.setLabel("Amount (৳)");BarChart<String,Number>chart=new BarChart<>(xAxis,yAxis);chart.setCategoryGap(18);chart.setBarGap(4);chart.setLegendVisible(true);chart.getStyleClass().add("monthly-bar-chart");XYChart.Series<String,Number>income=new XYChart.Series<>(),expenses=new XYChart.Series<>();income.setName("Income");expenses.setName("Expenses");List<Transaction>all=transactions.all(user.getId());for(int offset=5;offset>=0;offset--){YearMonth month=YearMonth.now().minusMonths(offset);String label=month.getMonth().getDisplayName(TextStyle.SHORT,Locale.ENGLISH);double in=all.stream().filter(t->t instanceof Income&&YearMonth.from(t.getDate()).equals(month)).mapToDouble(Transaction::getAmount).sum();double out=all.stream().filter(t->t instanceof Expense&&YearMonth.from(t.getDate()).equals(month)).mapToDouble(Transaction::getAmount).sum();income.getData().add(new XYChart.Data<>(label,in));expenses.getData().add(new XYChart.Data<>(label,out));}chart.getData().addAll(income,expenses);return chart;}
 private VBox card(String title,javafx.scene.Node content){VBox box=new VBox(8,new Label(title),content);box.getStyleClass().add("glass-card");box.setPadding(new Insets(14));VBox.setVgrow(content,Priority.ALWAYS);return box;}private String money(double amount){return String.format("৳%,.0f",amount);}private String clean(String text){return text.replace("u0026","&").replace("|","•");}
}
